INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 28, 'theory', 'Quiz: time, numbers, memory');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 0, 'What should you use to measure how long a piece of code runs?', '["SystemTime::now()", "Instant::now() and elapsed()", "thread::sleep", "Duration::default()"]', 1, 'Instant is monotonic and does not depend on clock changes; SystemTime can jump.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 1, 'What happens with Wrapping(255u8) + Wrapping(1)?', '["a panic", "a compile error", "you get Wrapping(0) even in debug mode", "Wrapping(256)"]', 2, 'Wrapping makes wrap-around part of the behavior; Saturating stops at the bound.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 2, 'Why does Option<NonZeroU32> take 4 bytes?', '["the compiler compresses numbers", "zero is freed up for None: a niche", "because u32 is not needed", "it is a mistake in the documentation"]', 1, 'A NonZero value can never be zero, and the compiler uses that value for None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 3, 'What does Duration::from_secs(1).checked_sub(Duration::from_secs(2)) return?', '["a negative duration", "Duration::ZERO", "a panic", "None"]', 3, 'There are no negative durations: checked_sub returns None, saturating_sub returns zero.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 4, 'Where in the Rust ecosystem do you look for random numbers?', '["the rand crate", "std::random", "std::num", "only in the operating system"]', 0, 'std has no random number generator; usually you use the rand crate.');
